def disponible(reservations, equipement, debut, fin):
    if not (debut >= 0 and debut < fin and fin <= 1440):
        return False
    for r in reservations:
        if r["active"] and r["equipement"] == equipement and debut < r["fin"] and r["debut"] < fin:
            return False
    return True

def compter_actives(reservations, equipement):
    nombre = 0
    for r in reservations:
        if r["active"] and r["equipement"] == equipement:
            nombre = nombre + 1
    return nombre

def duree_active(reservations, equipement):
    total = 0
    for r in reservations:
        if r["active"] and r["equipement"] == equipement:
            total = total + r["fin"] - r["debut"]
    return total

def conflits_ids(reservations, equipement, debut, fin):
    ids = []
    for r in reservations:
        if r["active"] and r["equipement"] == equipement and debut < r["fin"] and r["debut"] < fin:
            ids.append(r["id"])
    return sorted(ids)
